using System;using System.Linq;using System.Collections.Generic;using UnityEngine;
[Serializable] public sealed class KeyBindingRow {public string id,context,keyboard,pad;public KeyBindingRow Copy()=>new KeyBindingRow{id=id,context=context,keyboard=keyboard,pad=pad};}
[Serializable] public sealed class CharacterSlotPreference {public string characterId;public string[] operations;public int[] slots;}
[Serializable] public sealed class KeyConfigProfile {
 public int version=1;public KeyBindingRow[] bindings;public CharacterSlotPreference[] characters=new CharacterSlotPreference[0];
 public KeyConfigProfile Copy()=>JsonUtility.FromJson<KeyConfigProfile>(JsonUtility.ToJson(this));
 public KeyBindingRow Row(string id)=>Array.Find(bindings,x=>x.id==id);
 public static string SlotId(BattleAttackSlot slot)=>"battle."+slot;
 public static readonly string[] SystemIds={"battle.Hold","battle.Mania","battle.TRC","battle.Dash","training.Record","training.Play","training.Reset","menu.Confirm","menu.Cancel","common.Options","trigger.T1","trigger.T2"};
 public static KeyConfigProfile Defaults(TrainingInputConfig c){if(c==null||c.SlotKeys(false)==null||c.SlotKeys(false).Length!=9||c.slotGamepadBindings==null||c.slotGamepadBindings.Length!=9)throw new ArgumentException("Authored binding arrays must contain nine entries, including empty slots");var rows=new List<KeyBindingRow>();foreach(var slot in CharacterAttackSlot.DisplayOrder)rows.Add(new KeyBindingRow{id=SlotId(slot),context="Battle",keyboard=c.SlotKeys(false)[(int)slot],pad=c.slotGamepadBindings[(int)slot]});Action<string,string,string,string> add=(id,context,key,pad)=>rows.Add(new KeyBindingRow{id=id,context=context,keyboard=key,pad=pad});add("battle.Hold","Battle",c.firstThrowKeyboardBinding,"");add("battle.Mania","Battle","<Keyboard>/shift",c.maniaGamepadBinding);add("battle.TRC","Battle","<Keyboard>/semicolon",c.trcGamepadBinding);add("battle.Dash","Battle","<Keyboard>/space","");add("training.Record","Training","<Keyboard>/r",c.recordGamepadBinding);add("training.Play","Training","<Keyboard>/p",c.playGamepadBinding);add("training.Reset","Training","<Keyboard>/ctrl","");add("menu.Confirm","Menu","<Keyboard>/j","<Gamepad>/buttonEast");add("menu.Cancel","Menu","<Keyboard>/k","<Gamepad>/buttonSouth");add("common.Options","Global","<Keyboard>/escape","<Gamepad>/start");add("trigger.T1","Trigger","",c.modifier1Binding);add("trigger.T2","Trigger","",c.modifier2Binding);
  for(int m=1;m<=2;m++){var table=m==1?c.modifier1Actions:c.modifier2Actions;for(int i=0;i<9;i++){if(string.IsNullOrEmpty(c.slotGamepadBindings[i]))continue;string id=ActionId(table[i]);var row=rows.Find(x=>x.id==id);if(row!=null)row.pad="T"+m+"+"+c.slotGamepadBindings[i];}}return new KeyConfigProfile{bindings=rows.ToArray()};
 }
 static string ActionId(ModifiedInputAction a){switch(a){case ModifiedInputAction.A:return "battle.A";case ModifiedInputAction.B:return "battle.B";case ModifiedInputAction.C:return "battle.C";case ModifiedInputAction.X:return "battle.X";case ModifiedInputAction.Y:return "battle.Y";case ModifiedInputAction.Z:return "battle.Z";case ModifiedInputAction.J:return "battle.J";case ModifiedInputAction.K:return "battle.K";case ModifiedInputAction.L:return "battle.L";case ModifiedInputAction.Throw:return "battle.Hold";case ModifiedInputAction.Force:return "battle.Mania";case ModifiedInputAction.TRC:return "battle.TRC";case ModifiedInputAction.Dash:return "battle.Dash";case ModifiedInputAction.Record:return "training.Record";case ModifiedInputAction.Play:return "training.Play";case ModifiedInputAction.Reset:return "training.Reset";default:return "";}}
 public static string Normalize(string value)=>(value??"").Trim();public static string PathPart(string value){value=Normalize(value);return value.StartsWith("T1+",StringComparison.OrdinalIgnoreCase)||value.StartsWith("T2+",StringComparison.OrdinalIgnoreCase)?value.Substring(3):value;}
 public static int Modifier(string value)=>Normalize(value).StartsWith("T1+",StringComparison.OrdinalIgnoreCase)?1:Normalize(value).StartsWith("T2+",StringComparison.OrdinalIgnoreCase)?2:0;
 public static bool Same(string a,string b)=>string.Equals(Normalize(a),Normalize(b),StringComparison.OrdinalIgnoreCase);
 static bool PathSame(string a,string b){a=PathPart(a);b=PathPart(b);if(Same(a,b))return true;string[] families={"shift","ctrl"};foreach(var f in families){string root="<Keyboard>/";if((Same(a,root+f)&&(Same(b,root+"left"+f)||Same(b,root+"right"+f)))||(Same(b,root+f)&&(Same(a,root+"left"+f)||Same(a,root+"right"+f))))return true;}return false;}
 public static bool Overlap(KeyBindingRow a,KeyBindingRow b)=>a.context=="Trigger"||b.context=="Trigger"||a.context=="Global"||b.context=="Global"||a.context==b.context||a.context!="Menu"&&b.context!="Menu";
 public bool Validate(out string error){error=null;if(version!=1||bindings==null||characters==null||bindings.Length!=21){error="Unsupported or incomplete KeyConfig";return false;}var ids=new HashSet<string>();foreach(var row in bindings){if(row==null||!ids.Add(row.id)||!(SystemIds.Contains(row.id)||CharacterAttackSlot.DisplayOrder.Any(x=>SlotId(x)==row.id))){error="Invalid/duplicate action ID";return false;}string expected=row.id.StartsWith("battle.")?"Battle":row.id.StartsWith("training.")?"Training":row.id.StartsWith("menu.")?"Menu":row.id.StartsWith("trigger.")?"Trigger":"Global";if(row.context!=expected){error="Invalid context";return false;}foreach(bool pad in new[]{false,true}){string value=Normalize(pad?row.pad:row.keyboard);if(value.Length==0)continue;string path=PathPart(value);if(value.Length>160||path.IndexOf("+",StringComparison.Ordinal)>=0||!(path.StartsWith(pad?"<Gamepad>/":"<Keyboard>/",StringComparison.OrdinalIgnoreCase)||pad&&path.StartsWith("<Joystick>/",StringComparison.OrdinalIgnoreCase))){error="Invalid control path";return false;}if(row.context=="Trigger"&&Modifier(value)!=0){error="Trigger must be a single button";return false;}if(ReservedDirection(path)){error="方向入力として使用中です";return false;}}}
  foreach(bool pad in new[]{false,true})for(int i=0;i<bindings.Length;i++)for(int j=i+1;j<bindings.Length;j++){var a=bindings[i];var b=bindings[j];string av=pad?a.pad:a.keyboard,bv=pad?b.pad:b.keyboard;if(string.IsNullOrWhiteSpace(av)||string.IsNullOrWhiteSpace(bv)||!Overlap(a,b))continue;if((a.context=="Trigger"||b.context=="Trigger")&&PathSame(av,bv)){error="T1/T2は通常項目と重複できません";return false;}if(Modifier(av)==Modifier(bv)&&PathSame(av,bv)){error="Duplicate binding: "+a.id+" / "+b.id;return false;}}
  var chars=new HashSet<string>();foreach(var c in characters){if(c==null||string.IsNullOrWhiteSpace(c.characterId)||!chars.Add(c.characterId)||c.operations==null||c.slots==null||c.operations.Length!=9||c.slots.Length!=9||c.operations.Distinct().Count()!=9||c.slots.Distinct().Count()!=9||c.slots.Any(x=>x<0||x>8)||c.operations.Any(string.IsNullOrWhiteSpace)){error="Invalid character layout";return false;}}return true;
 }
 static bool ReservedDirection(string p){var names=new[]{"w","a","s","d","upArrow","downArrow","leftArrow","rightArrow"};if(names.Any(x=>Same(p,"<Keyboard>/"+x)))return true;return p.StartsWith("<Gamepad>/dpad",StringComparison.OrdinalIgnoreCase)||Same(p,"<Gamepad>/leftStick")||p.StartsWith("<Gamepad>/leftStick/",StringComparison.OrdinalIgnoreCase)||p.StartsWith("<Joystick>/stick",StringComparison.OrdinalIgnoreCase);}
 public bool TryBinding(string id,bool pad,string candidate,bool approveSwap,out string conflict,out string error){conflict=null;error=null;var row=Row(id);if(row==null){error="Unknown action";return false;}candidate=Normalize(candidate);string old=pad?row.pad:row.keyboard;if(Same(old,candidate))candidate="";if(!string.IsNullOrEmpty(candidate)&&bindings.Any(x=>x!=row&&(x.context=="Trigger"||row.context=="Trigger")&&Overlap(row,x)&&!string.IsNullOrWhiteSpace(pad?x.pad:x.keyboard)&&PathSame(candidate,pad?x.pad:x.keyboard))){error="T1/T2は同時利用する通常項目と交換できません";return false;}var conflicts=bindings.Where(x=>x!=row&&Overlap(row,x)&&!string.IsNullOrEmpty(candidate)&&Modifier(candidate)==Modifier(pad?x.pad:x.keyboard)&&PathSame(candidate,pad?x.pad:x.keyboard)&&!string.IsNullOrWhiteSpace(pad?x.pad:x.keyboard)).ToArray();if(conflicts.Length>1){error="複数の項目と重複します。別の入力を選んでください";return false;}if(conflicts.Length==1){conflict=conflicts[0].id;if(!approveSwap)return false;}var trial=Copy();var target=trial.Row(id);if(pad)target.pad=candidate;else target.keyboard=candidate;if(conflict!=null){var other=trial.Row(conflict);if(pad)other.pad=old;else other.keyboard=old;}if(!trial.Validate(out error))return false;bindings=trial.bindings;return true;}
 public CharacterSlotPreference Layout(TrainingApprovedCharacter character,bool create){var c=Array.Find(characters,x=>x.characterId==character.characterId);if(c==null&&create){c=new CharacterSlotPreference{characterId=character.characterId,operations=character.attackSlots.Select(OpId).ToArray(),slots=character.attackSlots.Select(x=>(int)x.slot).ToArray()};characters=characters.Concat(new[]{c}).ToArray();}return c;}
 public static string OpId(CharacterAttackSlot op)=>string.IsNullOrEmpty(op.operationId)?"origin."+op.slot:op.operationId;
 public int Slot(TrainingApprovedCharacter c,CharacterAttackSlot op){var layout=Layout(c,false);if(layout==null)return (int)op.slot;int i=Array.IndexOf(layout.operations,OpId(op));return i<0?(int)op.slot:layout.slots[i];}
 public void SwapOperation(TrainingApprovedCharacter c,string operation,int target){var layout=Layout(c,true);int i=Array.IndexOf(layout.operations,operation),j=Array.IndexOf(layout.slots,target);if(i<0||j<0)throw new ArgumentException("Unknown operation/slot");int old=layout.slots[i];layout.slots[i]=target;layout.slots[j]=old;}
}
